mapper.update:
UPDATE torrent_native_worker_instance
SET last_heartbeat_at=#{now},lease_until=#{until}
WHERE instance_id=#{id} AND lease_token=#{token}
  AND status='ACTIVE' AND lease_until > #{now}

mapper.select:
SELECT COUNT(*) FROM torrent_native_worker_instance
WHERE instance_id=#{id}
  AND (status='STOPPED' OR lease_until <= #{now})
